  Item_10105_StoryDesc = {
    Text = "Reine Hülle für Sie"
  },
  Item_10106_Desc = {
    Text = "Von Czort, dem stellvertretenden Dekan, genehmigte reichhaltige Versorgung.\nEine Holzbox mit wertvollen Materialien, die den Schutzherren bei der Durchführung der Trainings Unterstützung bietet.\nWählen Sie eines der folgenden Materialien aus:\nreine Geheimgeschichte*12\nGeist schärfen*12\nBewusstseinskopie*12\nGeistvorlage*12"
  },
  Item_10106_Name = {
    Text = "Ⅱ. Stufe Versorgung (veraltet)"
  },
  Item_10107_Desc = {
    Text = "Die Essenz des Bündnisses ist verbotene, schwer zu erkennende Wissen. Nach der Neuzeichnung mittels Druckplatten wird die Kraft des Bündnisses weiter verstärkt"
  },
  Item_10107_Name = {
    Text = "Bündnis Erweiterung (veraltet)"
  },
  Item_10108_Desc = {
    Text = "Eleganter Name für die Währung des Königreichs. Überall erhältlich, für alles notwendig"
  },
  Item_10108_Name = {
    Text = "Rosenskript"
  },
  Item_10110_Desc = {
