  Item_125189_Name = {
    Text = "Birnensirupbonbons"
  },
  Item_125190_Desc = {
    Text = "Nach der Aufzeichnung dieses Bandes kann die Bandenfertigkeit “Erinnerungen an das alte Herrenhaus“ bei der Formation ausgewählt werden.\n\nIm tiefen Herrenhaus sind zu viele Geheimnisse begraben, über Macht, über Besessenheit, über Verlangen.\nÜber den Blick, den der böse Gott auf die sterbliche Welt wirft, gefüllt mit Liebe, die “Vergnügen“ und “Verzerrung“ enthält."
  },
  Item_125190_Name = {
    Text = "Echos des Herrenhauses"
  },
