  Item_23906_Name = {Text = "Champagner"},
  Item_24056_Desc = {
    Text = "Sein Wert entspricht seinem glänzenden Aussehen.\nEine Versorgungskiste, die den Lumen-Kern aufbewahrt und den Geheimnisträgern bei der Ausführung ihrer Aufgaben hilft"
  },
  Item_24056_Name = {
    Text = "Lumen-Erweckungsversorgung"
