  Item_50032_Name = {
    Text = "Kieferknochen"
  },
  Item_51105_Desc = {
    Text = "Gegenstand, der im Ereignis “Die Magie der Geschichte·Klone“ nach dem Abschluss von “Drehbuchverwirrung“ oder dem Erfüllen von Veranstaltungsleistungen erhalten wird und im “Magischen Skriptladen“ gegen andere Dinge eingetauscht werden kann. \nEinblick verfliegt wie ein Meteorit, der durch den Nachthimmel rast. Der Unterschied ist, dass du die Möglichkeit hast, ihn für immer festzuhalten."
  },
  Item_51105_Name = {
    Text = "Wandernde Inspiration"
  },
  Item_51265_Desc = {
    Text = "Wird im Event „Die Magie der Geschichten · Reprint“ durch das Abschließen von „Skriptmythos“ oder das Erfüllen von Event-Erfolgen erhalten und dient als Tauschobjekt im „Magischen Skriptladen“.\nEinblick ist flüchtig, wie eine Sternschnuppe, die durch den Nachthimmel schießt. Der Unterschied ist: Du hast eine Möglichkeit, ihn für immer festzuhalten.\n\nMindestens {s1} Stück als Drop"
  },
