  Item_61391_Desc = {
    Text = "Das Rad des Schicksals mit der Eigenschaft Silberschlüsselaufladungsgrad"
  },
  Item_61391_Name = {Text = "Silberherz"},
  Item_61391_StoryDesc = {
    Text = "Es ist ein silbernes, klares, makelloses Herz. \n Es besteht aus reinem Silber und schlägt geordnet im mechanischen Herzen. \n Es wurde einst von Fleisch und Blut korrodiert und war einst von Schlamm befleckt. \n Doch als der Schatten des Todes sich senkte, kehrte es schließlich zu seiner ursprünglichen Gestalt zurück."
  },
  Item_61941_Desc = {
    Text = "Mondlicht hüllt sie in Silberweiß und feiert die Geburt eines unbezwingbaren Lebens.\nEine frisch erblühte Knospe auf dem Gipfel von Elworth, die zum Tauschen von Inventar bei „Zorn der Rache“ verwendet wird.\n\nDroppt mindestens {s1}"
  },
  Item_61941_Name = {
    Text = "Silberfrostknospe"
  },
  Item_61942_Desc = {
    Text = "Sonnenlicht hüllt sie in Goldgelb und feiert die Geburt eines unbezwingbaren Lebens.\nEine frisch erblühte Knospe auf dem Gipfel von Elworth, die zum Tauschen von Inventar bei „Hoffnung auf Auferstehung“ verwendet wird.\n\nDroppt mindestens {s1}"
  },
  Item_61942_Name = {
    Text = "Sonnenblumenknospe"
  },
  Item_61943_Desc = {
    Text = "Eis hüllt sie in tiefes Blau und feiert die Geburt eines unbezwingbaren Lebens.\nEine frisch erblühte Knospe auf dem Gipfel von Elworth, die zum Tauschen von Inventar bei „Unersättlicher Ehrgeiz“ verwendet wird.\n\nDroppt mindestens {s1}"
  },
  Item_61943_Name = {
