  Item_72089_Desc = {
    Text = "„Eicheln bedeuten den Beginn eines Abenteuers. Wir brauchen mehr Eicheln!“ – Ignatius. Eicheln, von Ignatius’ Magie geformt, verwendbar im „Runden-Tausch“ zum Erwerb von Ressourcen."
  },
  Item_72089_Name = {
    Text = "Magische Eichel"
  },
  Item_72089_StoryDesc = {
    Text = "Runde umkehren Verknüpfung"
  },
  Item_72095_Desc = {
    Text = "Nach der Aufzeichnung dieser Posse kann bei der Formation im „Phasenduell\" die Posse-Fähigkeit „Wirtshaus-Tür\" ausgewählt werden.\n\nWenn eine Welt untergeht, hat bereits der Prolog einer anderen Welt begonnen. Die Geschichte wird gemeinsam mit dem Wein immer wieder erzählt, doch die Zeit wird für alle Dinge eine Antwort schreiben."
  },
  Item_72095_Name = {
