  Item_80189_Name = {
    Text = "Superwert-Paket leer"
  },
  Item_80191_Desc = {
    Text = "Nach der Aufzeichnung dieses Schlüsselbefehls kann die Posse-Fähigkeit “Heilige Ausbesserung“ bei der Formation ausgewählt werden.\n\nSie hatte einst unzählige Patienten geheilt und ihnen den Weg zu einem Neugeboren gewiesen. All das hier ist nun auch nur eine psychotherapeutische Behandlung. \nDas Einzige, was diesmal besonders ist, ist, dass sie selbst die Patientin ist."
  },
  Item_80191_Name = {
    Text = "Heilige Ausbesserung"
  },
  Item_80191_StoryDesc = {
    Text = "Sie hatte einst unzählige Patienten geheilt und ihnen den Weg zu einem neuen Leben gewiesen. All das hier ist nun auch nur eine psychotherapeutische Behandlung. \nDas Einzige, was diesmal besonders ist, ist, dass sie selbst die Patientin ist."
  },
  Item_80192_Desc = {
    Text = "Die in der Seelenheilanstalt verstreuten emotionellen Partikel scheinen beim Berühren das Wimmern einer Person am Rande des Zusammenbruchs hörbar zu machen.\nWird verwendet, um den Ermittler bei der Untersuchung des Ereignisses „Metamorphose“ zu unterstützen."
  },
  Item_80192_Name = {
    Text = "Herz der Kognition"
  },
  Item_80285_Desc = {
    Text = "Nach dem Freischalten erhältst du folgende zusätzliche Belohnung, wenn du alle Aufgaben der “Erholungsreise“ abschließt."
  },
  Item_80285_Name = {
    Text = "Sanatorium-Chronik"
  },
  Item_81021_Desc = {
    Text = "Karens spezielles Reinigungswerkzeug, mit dem alles mühelos und gründlich gereinigt werden kann."
  },
  Item_81021_Name = {
    Text = "Reinigungswerkzeug"
  },
  Item_81069_Desc = {
    Text = "Die Logistikabteilung hat den Hütern, die einen “Ermittlungseinsatz“ abgeschlossen haben, eine Sondergenehmigung erteilt. Nach jedem Abschluss eines Ermittlungseinsatzes kann der Hüter eine spezielle Charge kostbarer Silberkernprodukte für den nächsten Einsatz erwerben. \nDie Anzahl ist begrenzt, möge der Silberne Schlüssel uns leiten."
  },
  Item_81069_Name = {
    Text = "Untersuchungserfolg · Sternenkapitel II"
  },
  Item_81250_Desc = {
    Text = "Eine Signalflagge mit der Bedeutung „Navigatorin ist an Bord dieses Schiffes“, die Kupferspange möglicherweise sammelt. Wird verwendet, um Waren im Laden zu tauschen."
  },
  Item_81250_Name = {
    Text = "Signalflagge"
  },
